"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { Check, X } from "./icons";

// Step: generated by UIX from the design system. Same variants and sizes as the Figma component.

const stepVariants = cva(
  "skin-quiet flex items-start gap-3",
  {
    variants: {
      status: {
        complete: "[&_[data-slot=indicator]]:bg-brand [&_[data-slot=indicator]]:text-fg-on-brand [&_[data-slot=title]]:text-fg-primary",
        current: "[&_[data-slot=indicator]]:bg-brand-subtle [&_[data-slot=indicator]]:border-2 [&_[data-slot=indicator]]:border-line-brand [&_[data-slot=indicator]]:text-fg-brand [&_[data-slot=title]]:text-fg-primary",
        upcoming: "[&_[data-slot=indicator]]:bg-surface [&_[data-slot=indicator]]:border-2 [&_[data-slot=indicator]]:border-line-default [&_[data-slot=indicator]]:text-fg-tertiary [&_[data-slot=title]]:text-fg-secondary",
        error: "[&_[data-slot=indicator]]:bg-danger-subtle [&_[data-slot=indicator]]:border-2 [&_[data-slot=indicator]]:border-line-danger [&_[data-slot=indicator]]:text-fg-danger [&_[data-slot=title]]:text-fg-danger",
      },
    },
    defaultVariants: {
      status: "complete",
    },
  },
);

export interface StepProps
  extends Omit<React.LiHTMLAttributes<HTMLLIElement>, "title">,
    VariantProps<typeof stepVariants> {
  /** Number shown in the circle while the step is current, upcoming or in error. */
  index?: number;
  title: React.ReactNode;
  description?: React.ReactNode;
}

const Step = React.forwardRef<HTMLLIElement, StepProps>(
  ({ className, status, index, title, description, ...props }, ref) => {
    const state = status ?? "complete";
    return (
      <li data-slot="stepper" data-kind="toggle" ref={ref} aria-current={state === "current" ? "step" : void 0} className={cn(stepVariants({ status }), className)} {...props}>
        <span data-slot="indicator" data-kind="toggle" className={cn("inline-flex shrink-0 items-center justify-center rounded-full size-8 text-label-medium [&_svg]:size-4", state === "complete" && "skin-solid")}>
          {state === "complete" ? <Check aria-hidden /> : state === "error" ? <X aria-hidden /> : index}
        </span>
        <span className="flex min-w-0 flex-col gap-0-5">
          <span data-slot="title" className="text-label-large">{title}</span>
          {description ? <span className="text-body-small text-fg-tertiary">{description}</span> : null}
        </span>
      </li>
    );
  },
);
Step.displayName = "Step";

const Stepper = React.forwardRef<HTMLOListElement, React.HTMLAttributes<HTMLOListElement>>(({ className, ...props }, ref) => (
  <ol ref={ref} className={cn("flex items-start gap-4", className)} {...props} />
));
Stepper.displayName = "Stepper";

export { Stepper, Step, stepVariants };
